return {rwwp01={id="rwwp01",name="柳树",dsc="柳树的树干粗壮而坚实，枝叶郁郁葱葱，看起来已有百年历史。细长的柳枝如同丝带一般随风飞舞，沙沙的声响，像是它在轻声低语。",canSee=1,caozuoName1="摘柳枝",buttonShow1=0,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="timechoice",args={"这柳树高耸，旁侧有一方青石伫立。那柳树最顶端的柳枝系着红布条，便是踩上那青石，也难以触及。而靠近顶端的柳枝更是纤细，难以借力。你思索片刻，决定——","10",{{"doc",{"CYN你一跃而起，以柳枝借力，可惜距离顶端仍差几寸，没摘到柳枝。NOR"}},{"gaintab",{"315002",2}},{"showbutton",{1,0}},{"refresh"}},{"扶风而上",{{"doc",{"CYN你一跃而起，以柳枝借力，宛若扶风而上，身形优雅，随后完美落地，可惜距离顶端仍差几寸，没摘到柳枝。NOR"}},{"gaintab",{"315002",2}},{"showbutton",{1,0}},{"refresh"}}},{"大鹏展翅",{{"doc",{"CYN你踏在青石上一跃而起，借力柳枝，宛如大鹏展翅，落地亦是威武，除去没摘到柳枝，挑不出一丝错误。NOR"}},{"gaintab",{"315002",2}},{"showbutton",{1,0}},{"refresh"}}},{"以叶为刃",{{"doc",{"CYN高手从不拘泥于一种方式，你随手摘下一片柳叶，飞射而出，削下了一根柳枝。NOR"}},{"itemin",{"2025qmdj01",1}},{"tips",{"获得柳枝*1"}},{"gaintab",{"315002",3}},{"showbutton",{1,0}},{"refresh"}}}}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"315002",1}}}},autoResult1={{type="showbutton",args={1,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={}},rwwp02={id="rwwp02",name="草丛",dsc="或细或粗的草叶挤在一起，将草丛之下遮掩得严严实实。时不时地传出一些细碎的声音，或许是野鼠穿过，也或许是长蛇爬过。",canSee=1,caozuoName1="查看",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="timechoice",args={"你小心翼翼地拨开草丛，说时迟那时快，一条大蛇猛地从草丛之中蹿了出来。","5",{{"doc",{"CYN你虽然反应稍慢了些许，但凭借着本能还是躲开了大蛇的袭击。那大蛇一击未中，又悄无声息地潜藏回草丛之内。NOR"}},{"addtab",{"315005",1}},{"showbutton",{1,0}},{"showbutton",{2,1}},{"refresh"}},{"避开",{{"doc",{"CYN你反应迅速，身形一闪，便避开了那大蛇。那大蛇一击未中，又悄无声息地潜藏回草丛之内，只留下草丛一阵轻微的晃动，仿佛它从未出现过一般。NOR"}},{"addtab",{"315005",1}},{"showbutton",{1,0}},{"showbutton",{2,1}},{"refresh"}}},{"斩杀",{{"doc",{"CYN你眼疾手快，猛地出手，一下子就击中了大蛇的七寸之处。那大蛇只挣扎了几下子，便瘫软下来，再不动弹了。你抬眼望向它窜出的草丛，见石缝后藏着一个普通竹筐，筐沿还挂着几片蛇蜕。NOR"}},{"addtab",{"315005",1}},{"gaintab",{"315006",1}},{"addobject",{"rwwp08"}},{"addobject",{"rwwp09"}},{"showbutton",{1,0}},{"showbutton",{2,1}},{"refresh"}}}}}},caozuoName2="查看",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN你轻轻拨开那一片草丛，什么特别的东西都没有。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"315006",1}}}},autoResult1={{type="change",args={"rwwp02","rwwp02c"}},{type="change",args={"rwwp02a","rwwp02c"}}},autoCondition2={relation="and",conditions={{type="tabgr",args={"315005",4}}}},autoResult2={{type="change",args={"rwwp02","rwwp02a"}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"315007",1}}}},autoResult3={{type="change",args={"rwwp02","rwwp02c"}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={}},rwwp03={id="rwwp03",name="草丛",dsc="或细或粗的草叶挤在一起，将草丛之下遮掩得严严实实。时不时地传出一些细碎的声音，或许是野鼠穿过，也或许是长蛇爬过。",canSee=1,caozuoName1="查看",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="timechoice",args={"你小心翼翼地拨开草丛，说时迟那时快，一条大蛇猛地从草丛之中蹿了出来。","5",{{"doc",{"CYN你虽然反应稍慢了些许，但凭借着本能还是躲开了大蛇的袭击。那大蛇一击未中，又悄无声息地潜藏回草丛之内。NOR"}},{"addtab",{"315005",1}},{"showbut