",conditions={{type="kick",args={}}}},result1={{type="itemin",args={"2025qmdj02",1}},{type="tips",args={"获得竹筐*1"}},{type="gaintab",args={"315003",3}},{type="outobject",args={"rwwp09"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={}},rwwp10={id="rwwp10",name="纸鸢",dsc="这纸鸢的绢布已经泛黄，但仍能看出昔日的精美，骨架由竹条编制而成，做工精细，应出自能工巧匠之手。显然它已经有些时日了，绢布变得脆弱，经受不住风的拉扯，撕裂后从空中坠下。",canSee=1,caozuoName1="查看",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"CYN你刚准备捡起纸鸢，一个老者牵着一位孩童，走到了你的面前，老者和孩童的表情一致带着心虚歉意。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL顾老爷：这位少侠，对不住嘞。那纸鸢突然失了控，砸着少侠了吧？实在是老朽的不是，还望少侠莫要怪罪。NOR"}},{type="addobject",args={"rwnpc03"}},{type="addobject",args={"rwnpc04"}},{type="gaintab",args={"315004",2}},{type="showbutton",args={1,0}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCond