,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={}},rwwp13={id="rwwp13",name="小墓",dsc="看起来就是一个小小的土堆，面前立着一块木板，上面用歪歪扭扭的笔迹写着“小黑之墓”，大概是怕随着时间的流逝会忘记小黑的模样，在木板最下面还画着一个简单的小黑狗画像。",canSee=1,caozuoName1="查看",buttonShow1=0,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"文本"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={}},rwwp14={id="rwwp14",name="隐脉图碑",dsc="六尺高九尺宽的石碑，上面刻着的便是传说中的隐脉图谱，虽说仍有诸多侠士质疑其真假，但据说如今已有人参悟。",canSee=1,caozuoName1="查看",buttonShow1=0,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"文本"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={}},rwwp15={id="rwwp15",name="武林众人",dsc="各路武林豪杰皆汇聚于此，武林盟不论正邪高低，只要遵守盟规皆一视同仁。你一眼望去，见到不少熟悉的面孔。",canSee=1,caozuoName1="查看",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL平遥公主：今日江湖各路英雄齐聚于此，实乃一大盛事，我也不再赘言，这便开宴！NOR"}},{type="gaintab",args={"315011",1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN只见众人正饮酒作乐，谈笑风生，清如水忽然起身，款步走向放置古琴之处。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL清如水：小女子愿为诸位弹曲助兴。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN清如水素手轻抚琴弦，琴音缓缓，宛如涓涓细流。初时，众人只觉这琴音美妙动听，然而，随着琴音袅袅，众人竟渐渐觉得脑袋昏沉起来，内息亦是紊乱不稳。NOR"}},{type="gaintab",args={"315011",2}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL李纯罡：我怎么忽然感觉头好晕，这酒……怕不是有问题！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL齐伯庸：师姐，别喝，这酒有毒！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL宝相神尼：不好，公主……剑岚快去看顾好公主！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL白扇子：酒没有问题，是这琴音……NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL任贤：哪来的小娘子，竟敢在此撒野作乱！使得什么邪术，还不快住手！NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL慕容业：箫秋山，清如水不是你师妹吗？这莫不是你们的圈套？以隐脉图作饵，召集我们前来，再下毒一网打尽！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL沈元龙：好大的胆子！你们是谁人指使？莫不是重光派来的奸细！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL欧阳川：老和尚，你不说两句吗？我记得这箫秋山是你引荐而来的吧，莫不是也被收买了！一起给我们下套呢！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL圆悲大师：阿弥陀佛，今日发生这般事情，贫僧与箫公子自是难辞其咎，此中是非曲直仍有端倪，莫要妄下定论。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL欧阳川：老和尚，别以为这事就此了结，你们得给我们一个说法吧！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL圆悲大师：阿弥陀佛，自然自然……NOR"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL白扇子：真是好大的一出戏，我们可都是为来着隐脉图来的，如今碑毁了，原本也丢了……NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL欧阳博：这不还有箫公子在，虽没了原本，但箫公子毕竟看过习过，既然能刻下一次，再刻下第二次应该也不是什么难事吧？NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL任贤：说得简单，谁知道这是不是他们一起做的戏！若是在再刻时稍做手脚，岂不是引人走火入魔！NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"315011",1}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"315011",2}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"315011",3}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"315011",6}}}},autoResult4={{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},autoCondition5={relation="and",conditions={{type="equaltab",args={"315011",8}}}},autoResult5={{type="showbutton",args={4,0}},{type="showbutton",args={6,1}}}},rwwp16={id="rwwp16",name="碎石碑",dsc="石碑已然碎裂成数块，七零八落地散于地上，其上所刻之图谱也模糊难辨了。",canSee=1,caozuoName1="查看",buttonShow1=0,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"文本"}}},buttonShow2=1,condition2={relati